window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[166]={"id":"166","numero":166,"titre":"Grippe","objectifs":[{"id":"166-1","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les modes de transmission de la grippe","contenu":"<div class=\"obj-callout success\"><strong>L'essentiel.</strong> La <span class=\"kw-etio\">grippe</span> se transmet de façon <span class=\"kw-def\">strictement interhumaine</span>, essentiellement par <span class=\"kw-clinique\">voie aérienne</span> via <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">gouttelettes</span>. Les <span class=\"kw-etio\">enfants</span> jouent un rôle majeur dans la dissémination d'une épidémie.</div>\n\n      <h4 class=\"kw-def\">Deux voies de transmission</h4>\n      <ul>\n        <li><strong>Directe (principale) :</strong> <span class=\"kw-clinique\">voie aérienne</span> via <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">gouttelettes</span> émises à la <span class=\"kw-clinique\">toux</span>, l'éternuement, la parole.</li>\n        <li><strong>Indirecte (accessoire) :</strong> <span class=\"kw-clinique\">manuportage</span> (mains, surfaces contaminées).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Contagiosité</h4>\n      <ul>\n        <li>Débute <span class=\"kw-chiffre\">1 jour avant</span> <span class=\"kw-clinique\">les</span> premiers symptômes.</li>\n        <li>Se prolonge jusqu'à <span class=\"kw-chiffre\">6 jours après</span> le début des symptômes.</li>\n        <li><span class=\"kw-clinique\">Taux d'attaque élevé</span> en cas de <span class=\"kw-def\">contact</span> proche et répété.</li>\n        <li>Transmission essentiellement <span class=\"kw-etio\">intra-familiale</span> et dans <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">collectivités</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>Réservoir.</strong> Le réservoir naturel du virus <span class=\"kw-def\">Influenza A</span> est l'<span class=\"kw-etio\">oiseau</span> 🦜 (réservoir aviaire).</div>","frequence":1},{"id":"166-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les moyens de surveillance épidémiologique","contenu":"<div class=\"callout callout-info\"><strong>Période & pilote.</strong> En période <span class=\"kw-def\">automno-hivernale</span> (<span class=\"kw-chiffre\">octobre à mars</span>), différents réseaux nationaux surveillent <span class=\"kw-clinique\">les</span> cas de <span class=\"kw-etio\">grippe</span>. <span class=\"kw-def\">Santé publique France</span> coordonne la <span class=\"kw-def\">surveillance</span>, via les cellules d'intervention en région (<span class=\"kw-def\">CIRE</span>). Ces données permettent à chaque médecin d'adapter son attitude devant un tableau respiratoire fébrile aigu. <strong>En cas de pandémie :</strong> information sur le site du <span class=\"kw-def\">ministère de la Santé</span> (alertes en cours + plan national de prévention « <span class=\"kw-def\">Pandémie grippale</span> »).</div>\n\n      <table >\n        <thead><tr><th>Secteur</th><th>Réseaux de surveillance</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Médecine ambulatoire</strong></td>\n            <td><strong><span class=\"kw-def\">Réseau Sentinelles</span> :</strong> remontée des <span class=\"kw-clinique\">syndromes grippaux</span> + prélèvements rhinopharyngés pour la <span class=\"kw-bio\">surveillance virologique</span><br>\n              <strong><span class=\"kw-def\">SOS Médecins</span> :</strong> nombre quotidien de <span class=\"kw-clinique\">consultations pour syndrome grippal</span> par région</td>\n          </tr>\n          <tr>\n            <td><strong>Hôpital</strong></td>\n            <td><strong><span class=\"kw-def\">Réseau Oscour</span> :</strong> <span class=\"kw-clinique\">passages aux urgences</span> et <span class=\"kw-clinique\">hospitalisations</span> pour <span class=\"kw-etio\">grippe</span><br>\n              <strong><span class=\"kw-alerte\">Réanimation</span> :</strong> <span class=\"kw-clinique\">admissions</span> pour <span class=\"kw-alerte\">grippe grave</span><br>\n              <strong><span class=\"kw-def\">Réseau Rénal-CNR</span> :</strong> <span class=\"kw-bio\">surveillance virologique</span> des patients hospitalisés</td>\n          </tr>\n          <tr>\n            <td><strong>Collectivités de personnes âgées</strong></td>\n            <td><span class=\"kw-def\">Surveillance</span> des <span class=\"kw-clinique\">infections respiratoires aiguës</span> → <span class=\"kw-alerte\">signalement des cas groupés d'IRA à l'ARS</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Mortalité</span></strong></td>\n            <td><strong><span class=\"kw-def\">INSEE</span>, <span class=\"kw-def\">CépiDc</span> :</strong> qualité dépendante du codage (<span class=\"kw-etio\">grippe</span>, complications, décompensations)</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"166-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître l’agent, les caractéristiques du virus","contenu":"<div class=\"obj-callout success\"><strong>Agent.</strong> Famille des <span class=\"kw-def\">Orthomyxoviridae</span>, genre <span class=\"kw-def\">Myxovirus influenzae</span>. Virus à <span class=\"kw-def\">ARN</span>, <span class=\"kw-clinique\">intracellulaire obligatoire</span> : il se multiplie dans <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">cellules épithéliales respiratoires</span>.</div>\n\n      <h4 class=\"kw-def\">Trois types selon <span class=\"kw-clinique\">les</span> glycoprotéines d'enveloppe</h4>\n      <ul>\n        <li><span class=\"kw-def\">Type A</span> — majoritaire, responsable des pandémies.</li>\n        <li><span class=\"kw-def\">Type B</span>.</li>\n        <li><span class=\"kw-def\">Type C</span>.</li>\n        <li><span class=\"kw-alerte\">Pas d'immunité croisée inter-types</span>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Structure du virion</h4>\n      <ul>\n        <li>Génome = <span class=\"kw-chiffre\">8 brins</span> indépendants d'<span class=\"kw-def\">ARN simple brin</span> (favorise <span class=\"kw-clinique\">les</span> réassortiments).</li>\n        <li><span class=\"kw-def\">Enveloppe lipidique</span> portant deux glycoprotéines clés :</li>\n        <li><strong><span class=\"kw-def\">Hémagglutinine (H)</span> :</strong> <span class=\"kw-clinique\">fixation du virus</span> aux cellules épithéliales respiratoires → <strong>entrée</strong> dans la cellule.</li>\n        <li><strong><span class=\"kw-def\">Neuraminidase (N)</span> :</strong> <span class=\"kw-clinique\">libération et dissémination</span> des virions → <strong>sortie</strong> de la cellule (cible des antiviraux).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Nomenclature</h4>\n      <p>Origine (réservoir animal, ou lieu géographique si origine humaine), Type, formule <span class=\"kw-def\">HxNy</span> — ex. <span class=\"kw-def\">Hong Kong / A / H3N2</span>.</p>\n\n      <h4 class=\"kw-def\"><span class=\"kw-def\">Physiopathologie</span> en 5 temps</h4>\n      <ol>\n        <li><span class=\"kw-clinique\">Inhalation</span> puis fixation à l'épithélium respiratoire via l'<span class=\"kw-def\">hémagglutinine</span>.</li>\n        <li><span class=\"kw-clinique\">Pénétration intracellulaire</span> et réplication.</li>\n        <li>Libération des nouveaux virions via la <span class=\"kw-def\">neuraminidase</span>.</li>\n        <li>Lésions par <span class=\"kw-alerte\">nécrose cellulaire</span> (cellules ciliées et productrices de mucus) + <span class=\"kw-clinique\">réaction inflammatoire de la sous-muqueuse</span> exposant la matrice extracellulaire.</li>\n        <li>Fixation des bactéries sur la matrice → <span class=\"kw-etio\">surinfection bactérienne</span> : <span class=\"kw-etio\">pneumocoque</span>, <span class=\"kw-etio\">S. aureus</span>, <span class=\"kw-etio\">H. influenzae</span> (et entérobactéries : <span class=\"kw-etio\">E. coli</span>, K. pneumoniae).</li>\n      </ol>\n\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Épidémiologie</span>.</strong> La maladie circule selon 2 modes : <strong>pandémique</strong> (<span class=\"kw-chiffre\">&gt; 30 %</span> de la population touchée) et <strong>endémo-épidémique saisonnière</strong> (<span class=\"kw-chiffre\">≈ 10 %</span> de la population mondiale par saison).</div>","frequence":1},{"id":"166-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une grippe","contenu":"<div class=\"callout callout-warn\"><strong>Dogme ⭐.</strong> L'apparition d'une <span class=\"kw-clinique\">toux fébrile</span> = <span class=\"kw-def\">grippe</span> jusqu'à preuve du contraire si elle survient : soit lors d'une <strong>épidémie de novembre à mars</strong> en Europe, soit après un <strong><span class=\"kw-def\">contact</span></strong> avec une personne atteinte. Le diagnostic est <span class=\"kw-def\">clinique</span>.</div>\n\n      <p><strong>Incubation :</strong> <span class=\"kw-chiffre\">1 à 3 jours</span>.</p>\n\n      <table >\n        <thead><tr><th>Phase</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Phase 1<br>(invasion)</strong></td>\n            <td>Début <span class=\"kw-alerte\">brutal</span> ; <span class=\"kw-clinique\">malaise général fébrile</span> : <span class=\"kw-clinique\">frissons</span>, <span class=\"kw-clinique\">fièvre élevée</span>, <span class=\"kw-clinique\">myalgies</span>, <span class=\"kw-clinique\">céphalées</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Phase 2<br>(état)</strong></td>\n            <td><em>Intensité inversement proportionnelle des signes généraux (importants) et des signes physiques (pauvres) :</em><br>\n              <strong>Généraux :</strong> <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">39-40 °C</span>, <span class=\"kw-clinique\">frissons</span>, <span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">anorexie</span>, abattement — courbe en <span class=\"kw-def\">V grippal</span> (chute à <span class=\"kw-chiffre\">2-3 j</span>, remontée au <span class=\"kw-chiffre\">4-5ᵉ j</span>)<br>\n              <strong>Syndrome algique diffus :</strong> <span class=\"kw-clinique\">céphalées frontales et rétro-orbitaires</span>, <span class=\"kw-clinique\">arthromyalgies</span>, <span class=\"kw-clinique\">lombalgies</span>, courbatures<br>\n              <strong>ORL :</strong> <span class=\"kw-clinique\">congestion nasale</span>, <span class=\"kw-clinique\">rhinorrhée</span><br>\n              <strong>Pharyngo-laryngite :</strong> <span class=\"kw-clinique\">douleurs pharyngo-laryngées</span>, <span class=\"kw-clinique\">dysphagie</span>, <span class=\"kw-clinique\">dysphonie</span><br>\n              <strong>Trachéo-bronchique :</strong> <span class=\"kw-clinique\">toux sèche et douloureuse</span> (brûlures rétrosternales)<br>\n              <strong>Signes physiques :</strong> <span class=\"kw-clinique\">énanthème pharyngé</span>, <span class=\"kw-clinique\">râles sous-crépitants</span></td>\n          </tr>\n          <tr>\n            <td><strong>Phase 3<br>(guérison)</strong></td>\n            <td><span class=\"kw-clinique\">Asthénie</span> et <span class=\"kw-clinique\">toux résiduelle</span> fréquentes (plusieurs semaines).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Durée.</strong> Phase d'invasion + phase d'état = <span class=\"kw-chiffre\">5 à 7 jours</span>.</div>","frequence":0},{"id":"166-5","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications de la grippe","contenu":"<table >\n        <thead><tr><th>Complication</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Grippe maligne primaire</span></td>\n            <td>Rare, grave, d'un seul tenant après la déclaration : <span class=\"kw-clinique\">pneumopathie alvéolo-interstitielle hypoxémiante</span> rapidement évolutive vers un <span class=\"kw-alerte\">SDRA</span>.<br>\n              <strong>CAT :</strong> <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-alerte\">réanimation</span> 🏥.</td>\n          </tr>\n          <tr>\n            <td><strong>Extra-respiratoires</strong></td>\n            <td><span class=\"kw-clinique\">Myocardite</span>, <span class=\"kw-clinique\">péricardite</span>, <span class=\"kw-clinique\">encéphalite</span>, <span class=\"kw-clinique\">rhabdomyolyse</span>, troubles digestifs (<span class=\"kw-clinique\">diarrhée</span>).<br>\n              <strong><span class=\"kw-alerte\">Syndrome de Reye</span> (rarissime) :</strong> sur <span class=\"kw-ci\">prise d'aspirine</span> au cours d'une <span class=\"kw-etio\">grippe</span> (surtout type <span class=\"kw-def\">B</span>, surtout chez l'<span class=\"kw-etio\">enfant</span>) → association <span class=\"kw-alerte\">encéphalite aiguë</span> + <span class=\"kw-alerte\">hépatite aiguë fulminante</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Grossesse</span></strong></td>\n            <td>Surmortalité maternelle (<span class=\"kw-clinique\">complications cardio-respiratoires</span>) ; risques fœtaux : <span class=\"kw-clinique\">avortement</span>, <span class=\"kw-clinique\">prématurité</span>.<br>\n              <span class=\"kw-alerte\">Le virus de la grippe n'est pas tératogène</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Surinfection bactérienne</span></td>\n            <td>Des voies aériennes supérieures : <span class=\"kw-clinique\">pneumonie bactérienne</span>, <span class=\"kw-clinique\">otite moyenne aiguë</span>, <span class=\"kw-clinique\">sinusite aiguë</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Drapeau — <span class=\"kw-clinique\">Syndrome de Reye</span>.</strong> Jamais d'<span class=\"kw-ci\">aspirine</span> chez l'enfant grippé : risque d'encéphalopathie aiguë + <span class=\"kw-alerte\">hépatite fulminante</span>.</div>","frequence":1},{"id":"166-6","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les terrains à risque de complications","contenu":"<div class=\"callout callout-warn\"><strong>Vigilance « <span class=\"kw-etio\">grippe</span> + <span class=\"kw-def\">terrain</span> ».</strong> Certains terrains exposent à la <span class=\"kw-alerte\">grippe grave</span> et/ou compliquée — ils définissent aussi <span class=\"kw-clinique\">les</span> indications du vaccin et du traitement <span class=\"kw-ttt\">antiviral</span>.</div>\n\n      <ul>\n        <li><span class=\"kw-etio\">Sujet âgé</span>, <span class=\"kw-etio\">nourrisson &lt; 6 mois</span>, <span class=\"kw-etio\">grossesse</span>.</li>\n        <li><span class=\"kw-etio\">Immunodéprimés</span>, <span class=\"kw-etio\">drépanocytose</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">obésité</span>.</li>\n        <li>Insuffisances <span class=\"kw-etio\">rénale</span>, <span class=\"kw-etio\">respiratoire</span>, <span class=\"kw-etio\">cardiaque</span> (à risque de <span class=\"kw-alerte\">décompensation</span>).</li>\n      </ul>","frequence":0},{"id":"166-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels","contenu":"<div class=\"callout callout-info\"><strong>Cadre.</strong> Devant une <span class=\"kw-clinique\">toux fébrile aiguë</span>, rester attentif aux diagnostics différentiels du <span class=\"kw-def\">syndrome grippal</span>, surtout hors période épidémique.</div>\n\n      <h4 class=\"kw-def\">Étiologies d'une <span class=\"kw-clinique\">toux</span> aiguë</h4>\n      <ul>\n        <li><strong>Infectieuses (virales / bactériennes) :</strong> <span class=\"kw-etio\">VRS</span>, <span class=\"kw-etio\">coronavirus</span> (dont SARS-CoV-2), <span class=\"kw-etio\">adénovirus</span>, <span class=\"kw-etio\">Bordetella</span> (coqueluche), <span class=\"kw-etio\">Mycoplasma pneumoniae</span>, <span class=\"kw-etio\">Chlamydia pneumoniae</span>.</li>\n        <li><strong>Pneumo-allergologiques :</strong> <span class=\"kw-etio\">allergie</span>, <span class=\"kw-etio\">asthme</span>.</li>\n        <li><strong>Mécaniques (± surinfection) :</strong> <span class=\"kw-etio\">tumeur</span>, <span class=\"kw-etio\">compression trachéale</span>, <span class=\"kw-etio\">corps étranger</span> (sujet âgé).</li>\n      </ul>\n\n      <p class=\"obj-source\"><em>Complété depuis le Collège de référence (PILLY étudiant 2023, item 166).</em></p>","frequence":0},{"id":"166-8","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les indications d’hospitalisation","contenu":"<div class=\"callout callout-warn\"><strong>Hospitaliser si :</strong></div>\n\n      <ul>\n        <li><strong><span class=\"kw-def\">Terrain</span> à risque :</strong> <span class=\"kw-etio\">sujet âgé</span>, <span class=\"kw-etio\">grossesse</span>, <span class=\"kw-etio\">immunodéprimé</span>, <span class=\"kw-etio\">nourrisson</span>.</li>\n        <li><strong><span class=\"kw-etio\">Grippe</span> avec complication significative :</strong> <span class=\"kw-alerte\">grippe maligne</span>, <span class=\"kw-alerte\">pneumonie secondaire</span>, <span class=\"kw-alerte\">myocardite / péricardite</span>, <span class=\"kw-alerte\">méningo-encéphalite</span>.</li>\n      </ul>","frequence":0},{"id":"166-9","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications et non indication des examens paracliniques","contenu":"<div class=\"callout callout-danger\"><strong>Règle d'or.</strong> <span class=\"kw-alerte\">Aucun examen microbiologique</span> en cas de <span class=\"kw-def\">grippe saisonnière non compliquée</span> ❌ — le diagnostic est clinique.</div>\n\n      <h4 class=\"kw-def\">Indications d'un examen microbiologique</h4>\n      <ul>\n        <li>Visée <span class=\"kw-bio\">épidémiologique</span> (médecin du réseau Sentinelles).</li>\n        <li>Visée <span class=\"kw-bio\">étiologique</span> chez un patient <span class=\"kw-etio\">hospitalisé</span> avec complications respiratoires ou extra-respiratoires (pour guider <span class=\"kw-clinique\">les</span> précautions d'hygiène et le traitement).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Autres examens (selon contexte)</h4>\n      <ul>\n        <li><strong>Biologie :</strong> <span class=\"kw-bio\">syndrome inflammatoire</span> en cas de surinfection <span class=\"kw-etio\">bactérienne</span> (non spécifique).</li>\n        <li><strong>Imagerie :</strong> <span class=\"kw-imagerie\">radiographie thoracique</span> si <span class=\"kw-clinique\">doute diagnostique</span> ou <span class=\"kw-clinique\">complications</span> — peut être normale, montrer un <span class=\"kw-imagerie\">syndrome alvéolo-interstitiel bilatéral</span> (pneumonie grippale primaire) ou une <span class=\"kw-imagerie\">condensation parenchymateuse</span> (pneumonie <span class=\"kw-etio\">bactérienne</span> secondaire).</li>\n      </ul>","frequence":0},{"id":"166-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les techniques de prélèvements à la recherche de grippe","contenu":"<table >\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Prélèvements</strong></td>\n            <td><span class=\"kw-bio\">Écouvillonnage nasopharyngé profond</span> ++ (avec matériel adapté)<br>\n              <span class=\"kw-bio\">Prélèvements respiratoires profonds</span></td>\n          </tr>\n          <tr>\n            <td><strong>Analyses</strong></td>\n            <td><strong><span class=\"kw-bio\">PCR Myxovirus influenzae</span> :</strong> examen de <span class=\"kw-def\">référence</span><br>\n              <strong><span class=\"kw-bio\">TROD</span> (détection d'Ag viraux : ELISA, <span class=\"kw-bio\">immunofluorescence</span>) :</strong> <span class=\"kw-alerte\">sensibilité limitée</span>, non recommandé hors période de circulation <span class=\"kw-etio\">virale</span> intense</td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"166-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement symptomatique","contenu":"<div class=\"obj-callout success\"><strong>Base du traitement.</strong> <span class=\"kw-ttt\">Antalgiques</span> / <span class=\"kw-ttt\">antipyrétiques</span> si <span class=\"kw-clinique\">fièvre</span> mal tolérée : <span class=\"kw-ttt\">paracétamol</span> en <span class=\"kw-chiffre\">première intention</span>.</div>\n\n      <div class=\"callout callout-danger\"><strong>À proscrire ❌.</strong> <span class=\"kw-ci\">AINS</span>, <span class=\"kw-ci\">aspirine</span>, <span class=\"kw-ci\">corticoïdes</span>, <span class=\"kw-ci\">antitussifs</span> et <span class=\"kw-ci\">fluidifiants bronchiques</span>.</div>\n\n      <p><strong><span class=\"kw-ttt\">Antibiothérapie</span> :</strong> justifiée uniquement en cas de <span class=\"kw-clinique\">pneumonie bactérienne post-grippale</span> → <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> pendant <span class=\"kw-chiffre\">7 jours</span>.</p>","frequence":1},{"id":"166-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître les traitements spécifiques : indication, molécules","contenu":"<h4 class=\"kw-def\">Molécules — inhibiteurs de la neuraminidase</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Oseltamivir</span> per os.</li>\n        <li><span class=\"kw-ttt\">Zanamivir</span> par voie inhalée.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Quand débuter ?</strong> Efficacité corrélée à la <strong>précocité</strong> d'administration : au mieux <span class=\"kw-chiffre\">&lt; 48 h</span>, <span class=\"kw-alerte\">sans attendre la confirmation virologique</span>.</div>\n\n      <h4 class=\"kw-def\">Durée</h4>\n      <ul>\n        <li><strong>Curatif :</strong> <span class=\"kw-chiffre\">5 jours</span>, <span class=\"kw-chiffre\">2×/jour</span>.</li>\n        <li><strong>Préventif (post-exposition) :</strong> <span class=\"kw-chiffre\">10 jours</span>, <span class=\"kw-chiffre\">1×/jour</span>.</li>\n      </ul>\n\n      <table >\n        <thead><tr><th>Situation</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Curatif</strong><br>(patient symptomatique)</td>\n            <td><span class=\"kw-alerte\">Grippe grave d'emblée</span> ou <span class=\"kw-etio\">grippe</span> requérant une <span class=\"kw-alerte\">hospitalisation</span><br>\n              Personnes <span class=\"kw-chiffre\">&gt; 1 an</span> à risque de complications, y compris <span class=\"kw-etio\">femmes enceintes</span> (= personnes relevant d'une indication vaccinale)</td>\n          </tr>\n          <tr>\n            <td><strong>Préemptif curatif</strong></td>\n            <td><span class=\"kw-def\">Contact</span> étroit avéré chez un patient <span class=\"kw-clinique\">asymptomatique</span> à haut risque (<span class=\"kw-etio\">immunodéprimé</span> ou <span class=\"kw-def\">comorbidité</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Prophylactique post-exposition</strong></td>\n            <td>Personnes <span class=\"kw-chiffre\">&gt; 1 an</span> à risque, y compris <span class=\"kw-etio\">femmes enceintes</span><br>\n              Collectivités de personnes à risque (personnes âgées institutionnalisées)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Femme enceinte.</strong> <span class=\"kw-ttt\">Vaccination</span> = meilleure protection (possible à <strong>tous <span class=\"kw-clinique\">les</span> trimestres</strong>, vaccins inactivés). En post-exposition : <span class=\"kw-ttt\">oseltamivir</span> ; <span class=\"kw-clinique\">allaitement toujours possible</span> ✅.</div>","frequence":1},{"id":"166-13","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les mesures de prévention de la transmission","contenu":"<table >\n        <thead><tr><th>Contexte</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Patient hospitalisé</strong></td>\n            <td><span class=\"kw-def\">Précautions complémentaires</span> <span class=\"kw-alerte\">gouttelettes</span> ; <span class=\"kw-clinique\">chambre individuelle</span>, porte fermée ; mesures d'hygiène.</td>\n          </tr>\n          <tr>\n            <td><strong>Patient ambulatoire</strong></td>\n            <td><span class=\"kw-clinique\">Repos à domicile</span>, <span class=\"kw-clinique\">arrêt de travail</span> (éviter la transmission), mesures d'hygiène : couvrir bouche/nez à la <span class=\"kw-clinique\">toux</span> et aux éternuements, mouchoirs à usage unique en poubelle fermée, <span class=\"kw-clinique\">lavage des mains</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Prophylaxie post-exposition</span></strong></td>\n            <td><span class=\"kw-ttt\">Oseltamivir</span> per os pendant <span class=\"kw-chiffre\">10 jours</span> dans certaines situations (notamment <span class=\"kw-etio\">cas groupés en établissement hébergeant des personnes âgées</span>).</td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"166-14","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les indications du vaccin anti-grippal","contenu":"<div class=\"obj-callout success\"><strong>Le vaccin.</strong> Vaccin <span class=\"kw-def\">viral inactivé</span>, <span class=\"kw-def\">quadrivalent</span> (<span class=\"kw-chiffre\">2 souches A</span> + <span class=\"kw-chiffre\">2 souches B</span>), <span class=\"kw-ttt\">1 injection intramusculaire</span>. Composition réactualisée chaque année → <strong>vacciner tous <span class=\"kw-clinique\">les</span> ans à l'automne</strong>.</div>\n\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indication</span>.</strong> <span class=\"kw-ci\">Allergie à l'ovalbumine</span> (protéine de l'œuf).</div>\n\n      <h4 class=\"kw-def\">Efficacité</h4>\n      <ul>\n        <li>Prévient la <span class=\"kw-etio\">grippe</span> chez <span class=\"kw-chiffre\">≈ 70 %</span> des adultes sains et réduit <span class=\"kw-clinique\">les</span> complications.</li>\n        <li>Moins efficace chez le <span class=\"kw-etio\">sujet âgé</span> et l'<span class=\"kw-etio\">immunodéprimé</span>, mais réduit l'<span class=\"kw-def\">incidence</span> des complications.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Indications</h4>\n      <ul>\n        <li><strong>Population générale :</strong> adulte <span class=\"kw-chiffre\">&gt; 65 ans</span>.</li>\n        <li><strong><span class=\"kw-def\">Comorbidités</span></strong> (indications larges) : affections <span class=\"kw-etio\">bronchopulmonaires chroniques</span> (<span class=\"kw-etio\">asthme</span>, <span class=\"kw-etio\">BPCO</span>), <span class=\"kw-etio\">cardiopathies</span> / <span class=\"kw-etio\">insuffisance cardiaque</span> graves, <span class=\"kw-etio\">troubles du rythme</span>, <span class=\"kw-etio\">coronaropathie</span>, ATCD d'<span class=\"kw-etio\">AVC</span>, affections <span class=\"kw-etio\">neuro-musculaires</span> graves, para-/tétraplégie avec atteinte diaphragmatique, <span class=\"kw-etio\">néphropathies chroniques</span> graves / <span class=\"kw-etio\">syndrome néphrotique</span>, <span class=\"kw-etio\">diabète</span> (type 1 et 2), <span class=\"kw-etio\">déficits immunitaires</span>, <span class=\"kw-etio\">drépanocytose</span>, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">maladie hépatique chronique</span>.</li>\n        <li><strong>Recommandations particulières :</strong> <span class=\"kw-etio\">femmes enceintes</span> ⭐ (quel que soit le trimestre), patient <span class=\"kw-chiffre\">≥ 6 mois</span> avec <span class=\"kw-def\">comorbidités</span>, <span class=\"kw-etio\">obèse IMC &gt; 40</span>, séjour en SSR / établissement médico-social, entourage des nourrissons &lt;<span class=\"kw-chiffre\"> 6 mois</span> et des prématurés.</li>\n        <li><strong>Professionnels</strong> (recommandé, non obl<span class=\"kw-chiffre\">iga</span>toire) : professionnels de santé / en <span class=\"kw-def\">contact</span> avec des sujets à risque, personnels navigants, guides touristiques, personnels exposés aux virus porcins et aviaires.</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>Bénéfice indirect.</strong> Le passage des <span class=\"kw-bio\">anticorps anti-grippaux</span> maternels <span class=\"kw-clinique\">protège le nouveau-né et le nourrisson</span>, non vaccinables avant <span class=\"kw-chiffre\">6 mois</span>.</div>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-etio\">grippe</span> saisonnière le plus souvent <span class=\"kw-def\">bénigne et ambulatoire</span> ; l'urgence vitale = <span class=\"kw-alerte\">grippe maligne primaire</span> (<span class=\"kw-clinique\">pneumopathie alvéolo-interstitielle hypoxémiante</span> évoluant vers un <span class=\"kw-alerte\">SDRA</span>) → <span class=\"kw-alerte\">réanimation</span>.<br><strong>Fenêtre thérapeutique :</strong> <span class=\"kw-ttt\">antiviral</span> (<span class=\"kw-ttt\">oseltamivir</span>) d'autant plus efficace qu'il est précoce, au mieux <span class=\"kw-chiffre\">&lt; 48 h</span>, <span class=\"kw-alerte\">sans attendre la confirmation virologique</span>.<br><strong>1er geste :</strong> <span class=\"kw-ttt\">paracétamol</span> si <span class=\"kw-clinique\">fièvre</span> mal tolérée et <span class=\"kw-ci\">proscrire AINS, aspirine, corticoïdes</span> ; diagnostic <span class=\"kw-def\">clinique</span> (<span class=\"kw-clinique\">toux</span> fébrile en épidémie ou après <span class=\"kw-def\">contact</span>).</p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-def\">grippe saisonnière non compliquée</span> du sujet sain — <span class=\"kw-ttt\">repos à domicile</span>, <span class=\"kw-ttt\">arrêt de travail</span>, mesures d'hygiène.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> <span class=\"kw-etio\">terrain à risque</span> (<span class=\"kw-etio\">sujet âgé</span>, <span class=\"kw-etio\">grossesse</span>, <span class=\"kw-etio\">immunodéprimé</span>, <span class=\"kw-etio\">nourrisson</span>) ou <span class=\"kw-alerte\">complication significative</span> (<span class=\"kw-alerte\">grippe maligne</span>, <span class=\"kw-alerte\">pneumonie secondaire</span>, <span class=\"kw-alerte\">myocardite / péricardite</span>, <span class=\"kw-alerte\">méningo-encéphalite</span>).<br><strong><span class=\"kw-alerte\">Réanimation</span> :</strong> <span class=\"kw-alerte\">grippe maligne primaire</span>.<br><strong><span class=\"kw-def\">Isolement</span> :</strong> patient hospitalisé → <span class=\"kw-def\">précautions complémentaires</span> <span class=\"kw-alerte\">gouttelettes</span>, <span class=\"kw-ttt\">chambre individuelle</span> porte fermée.</p>","redflags":"<ul><li><span class=\"kw-alerte\">FR &gt; 30/min</span></li><li><span class=\"kw-alerte\">PAS &lt; 90 mmHg</span></li><li><span class=\"kw-alerte\">FC &gt; 120 bpm</span></li><li><span class=\"kw-alerte\">Troubles des fonctions supérieures</span></li><li><span class=\"kw-alerte\">Grippe maligne primaire</span> : <span class=\"kw-clinique\">pneumopathie hypoxémiante</span> rapidement évolutive vers un <span class=\"kw-alerte\">SDRA</span></li><li>Complications extra-respiratoires : <span class=\"kw-alerte\">myocardite</span>, <span class=\"kw-alerte\">péricardite</span>, <span class=\"kw-alerte\">encéphalite</span>, <span class=\"kw-alerte\">rhabdomyolyse</span></li><li><span class=\"kw-etio\">Surinfection bactérienne</span> : <span class=\"kw-alerte\">pneumonie bactérienne secondaire</span></li><li>Présence d'un <span class=\"kw-etio\">terrain à risque</span> de complications</li></ul>","principes":"<p>Traitement essentiellement <span class=\"kw-ttt\">symptomatique</span> ; <span class=\"kw-ttt\">antiviral</span> et antibiotiques réservés à des indications précises ; <span class=\"kw-ttt\">vaccination</span> = prévention de référence.</p><p><strong>Traitement symptomatique</strong></p><p>À proscrire : <span class=\"kw-ci\">AINS</span>, <span class=\"kw-ci\">aspirine</span>, <span class=\"kw-ci\">corticoïdes</span>, <span class=\"kw-ci\">antitussifs</span>, <span class=\"kw-ci\">fluidifiants bronchiques</span></p><ul><li><span class=\"kw-ttt\">Antalgiques / antipyrétiques</span> si <span class=\"kw-clinique\">fièvre</span> mal tolérée : <span class=\"kw-ttt\">paracétamol</span></li></ul><p><strong>Traitement <span class=\"kw-ttt\">antiviral</span> (inhibiteurs de la neuraminidase)</strong></p><p>Indications curatif : <span class=\"kw-alerte\">grippe grave d'emblée</span> ou hospitalisée, personnes <span class=\"kw-chiffre\">&gt; 1 an</span> à risque de complications (dont <span class=\"kw-etio\">femmes enceintes</span>)</p><ul><li><span class=\"kw-ttt\">Oseltamivir</span> per os ; <span class=\"kw-ttt\">zanamivir</span> par voie inhalée</li><li>Débuter <span class=\"kw-chiffre\">&lt; 48 h</span>, <span class=\"kw-alerte\">sans attendre la confirmation virologique</span></li><li>Curatif : <span class=\"kw-chiffre\">5 jours</span>, <span class=\"kw-chiffre\">2×/jour</span></li><li>Préventif (post-exposition) : <span class=\"kw-chiffre\">10 jours</span>, <span class=\"kw-chiffre\">1×/jour</span></li></ul><p><strong><span class=\"kw-ttt\">Antibiothérapie</span></strong></p><ul><li>Justifiée uniquement si <span class=\"kw-etio\">pneumonie bactérienne post-grippale</span></li><li><span class=\"kw-ttt\">Amoxicilline-acide clavulanique</span> pendant <span class=\"kw-chiffre\">7 jours</span></li></ul><p><strong>Prévention</strong></p><p><span class=\"kw-ci\">Contre-indication</span> vaccinale : <span class=\"kw-ci\">allergie à l'ovalbumine</span> (protéine de l'œuf)</p><ul><li><span class=\"kw-ttt\">Vaccin viral inactivé quadrivalent</span>, <span class=\"kw-ttt\">1 injection IM</span>, tous <span class=\"kw-clinique\">les</span> ans à l'automne</li><li>Recommandé : adulte <span class=\"kw-etio\">&gt; 65 ans</span>, <span class=\"kw-def\">comorbidités</span>, <span class=\"kw-etio\">femmes enceintes</span> (tout trimestre)</li><li>Précautions <span class=\"kw-alerte\">gouttelettes</span> et mesures d'hygiène</li></ul>","suivi":"<p><strong><span class=\"kw-clinique\">Évolution</span> :</strong> guérison en <span class=\"kw-chiffre\">5 à 7 jours</span> ; <span class=\"kw-clinique\">asthénie</span> et <span class=\"kw-clinique\">toux résiduelle</span> fréquentes pendant plusieurs semaines.<br><strong>Dépister <span class=\"kw-clinique\">les</span> complications :</strong> <span class=\"kw-etio\">surinfection bactérienne</span> (pneumonie, OMA, sinusite) → <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> ; <span class=\"kw-def\">surveillance</span> rapprochée si <span class=\"kw-alerte\">grippe maligne</span>.<br><strong>Arrêt de l'<span class=\"kw-ttt\">antiviral</span> :</strong> possible si <span class=\"kw-bio\">RT-PCR négative</span> chez le cas index.<br><strong>Contagiosité :</strong> <span class=\"kw-def\">isolement</span> et <span class=\"kw-ttt\">arrêt de travail</span> jusqu'à <span class=\"kw-chiffre\">6 jours</span> après le début des symptômes.</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-166.pdf","label":"Collège (PILLY étudiant 2023) — item 166"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion de <span class=\"kw-etio\">grippe</span> — <span class=\"kw-clinique\">Toux fébrile</span> aiguë en <span class=\"kw-def\">épidémie (nov.–mars)</span> ou après <span class=\"kw-etio\">contact</span> → diagnostic <span class=\"kw-def\">clinique</span> jusqu'à preuve du contraire","detail":"<h4>CAT — <span class=\"kw-etio\">Grippe</span> — <span class=\"kw-clinique\">Toux</span> fébrile aiguë en période épidémique (nov.–mars) ou après <span class=\"kw-def\">contact</span></h4>","branches":[{"to":"t-rea","label":"Signe de gravité ou complication significative","color":"red"},{"to":"q-terrain","label":"Pas de signe de gravité","color":"blue"}]},{"id":"t-rea","kind":"terminal","label":"Grippe grave — hospitalisation — Réanimation si grippe maligne","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">FR &gt; 30/min</span>, <span class=\"kw-alerte\">PAS &lt; 90 mmHg</span>, <span class=\"kw-alerte\">FC &gt; 120 bpm</span>, <span class=\"kw-alerte\">troubles des fonctions supérieures</span></li><li>Ou <span class=\"kw-alerte\">complication significative</span> : <span class=\"kw-alerte\">grippe maligne</span>, <span class=\"kw-alerte\">pneumonie secondaire</span>, <span class=\"kw-alerte\">myocardite / péricardite</span>, <span class=\"kw-alerte\">méningo-encéphalite</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">PCR Myxovirus influenzae</span> sur <span class=\"kw-bio\">écouvillonnage nasopharyngé profond</span> (justifiée chez le patient hospitalisé avec complications)</li><li><span class=\"kw-imagerie\">Radiographie thoracique</span> : <span class=\"kw-radio\">syndrome alvéolo-interstitiel bilatéral</span> (<span class=\"kw-etio\">grippe</span> maligne) ou <span class=\"kw-radio\">condensation parenchymateuse</span> (pneumonie <span class=\"kw-etio\">bactérienne</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Oseltamivir</span> per os curatif d'emblée, <span class=\"kw-chiffre\">&lt; 48 h</span>, <span class=\"kw-alerte\">sans attendre la virologie</span></li><li>Précautions <span class=\"kw-alerte\">gouttelettes</span>, <span class=\"kw-ttt\">chambre individuelle</span></li><li><span class=\"kw-alerte\">Grippe maligne primaire</span> → <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-alerte\">réanimation</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie</span> (<span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> <span class=\"kw-chiffre\">7 jours</span>) si <span class=\"kw-etio\">pneumonie bactérienne</span> associée</li></ul>"},{"id":"q-terrain","kind":"decision","label":"<span class=\"kw-def\">Terrain</span> à risque de complications ? — <span class=\"kw-etio\">Âge extrême</span>, <span class=\"kw-etio\">grossesse</span>, <span class=\"kw-etio\">immunodépression</span> ou <span class=\"kw-def\">comorbidité</span>","branches":[{"to":"t-risque","label":"Oui — terrain à risque","color":"amber"},{"to":"t-ambu","label":"Non — sujet sain","color":"green"}]},{"id":"t-risque","kind":"terminal","label":"Terrain à risque — antiviral curatif + surveillance","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-def\">Terrain</span> à risque : <span class=\"kw-etio\">sujet âgé</span>, <span class=\"kw-etio\">nourrisson &lt; 6 mois</span>, <span class=\"kw-etio\">grossesse</span>, <span class=\"kw-etio\">immunodéprimé</span></li><li><span class=\"kw-etio\">Drépanocytose</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">obésité</span>, insuffisance <span class=\"kw-etio\">rénale</span> / <span class=\"kw-etio\">respiratoire</span> / <span class=\"kw-etio\">cardiaque</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Oseltamivir</span> per os curatif <span class=\"kw-chiffre\">&lt; 48 h</span> : <span class=\"kw-chiffre\">5 jours</span>, <span class=\"kw-chiffre\">2×/jour</span> (femme enceinte : quel que soit le trimestre)</li><li>Symptomatique : <span class=\"kw-ttt\">paracétamol</span> ; <span class=\"kw-ci\">proscrire AINS, aspirine, corticoïdes, antitussifs, fluidifiants</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-alerte\">Hospitalisation à discuter</span> selon le <span class=\"kw-def\">terrain</span> ; dépister la <span class=\"kw-etio\">surinfection bactérienne</span></li><li>Prélèvement virologique en cas de <span class=\"kw-clinique\">signes de gravité</span> ou de <span class=\"kw-def\">comorbidités</span></li></ul>"},{"id":"t-ambu","kind":"terminal","label":"Grippe saisonnière non compliquée — ambulatoire","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-def\">Grippe saisonnière non compliquée</span> du sujet sain, sans <span class=\"kw-clinique\">signe de gravité</span> ni <span class=\"kw-def\">comorbidité</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-alerte\">Aucun examen microbiologique</span> : le diagnostic est <span class=\"kw-def\">clinique</span></li></ul><h4>Traitement</h4><ul><li>Symptomatique seul : <span class=\"kw-ttt\">paracétamol</span> si <span class=\"kw-clinique\">fièvre</span> mal tolérée</li><li><span class=\"kw-ci\">Proscrire AINS, aspirine, corticoïdes, antitussifs, fluidifiants bronchiques</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Repos à domicile</span>, <span class=\"kw-ttt\">arrêt de travail</span>, mesures d'hygiène (précautions <span class=\"kw-alerte\">gouttelettes</span>)</li><li>Guérison en <span class=\"kw-chiffre\">5 à 7 jours</span> ; <span class=\"kw-clinique\">asthénie</span> et <span class=\"kw-clinique\">toux résiduelle</span> possibles plusieurs semaines</li></ul>"}]},"cards":[{"i":"1e459c1118b1","n":166,"o":"166-1","u":"Physiopathologie","t":"Connaître les modes de transmission de la grippe","q":"Quels sont les rôles des enfants et des foyers dans la dissémination de l'épidémie de grippe ?","a":"<p>Les <strong>enfants</strong> jouent un <strong>rôle majeur</strong> dans la dissémination d'une épidémie de grippe. La transmission est essentiellement <strong>intra-familiale</strong> et dans les <strong>collectivités</strong>, avec un taux d'attaque élevé en cas de contact proche et répété.</p>"},{"i":"636d4e4af8a2","n":166,"o":"166-1","u":"Physiopathologie","t":"Connaître les modes de transmission de la grippe","q":"Quelle est la période de contagiosité de la grippe ?","a":"<p>La contagiosité de la grippe débute <strong>1 jour avant les premiers symptômes</strong> et se prolonge généralement jusqu'à <strong>6 jours après le début des symptômes</strong>.</p>"},{"i":"958e4db2069f","n":166,"o":"166-1","u":"Physiopathologie","t":"Connaître les modes de transmission de la grippe","q":"Quel est le mode de transmission principal de la grippe chez l'être humain ?","a":"<p>La transmission principale de la grippe est <strong>directe</strong> et <strong>interhumaine</strong>, essentiellement par <strong>voie aérienne</strong> via les <strong>gouttelettes</strong> émises lors de la toux, des éternuements ou de la parole.</p>"},{"i":"32315e3ff719","n":166,"o":"166-11","u":"Prise en charge","t":"Connaître le traitement symptomatique","q":"Quel est le traitement symptomatique de la grippe le plus approprié en première intention ?","a":"<p>Le traitement symptomatique de la grippe repose en première intention sur le <strong>paracétamol</strong>, notamment en cas de fièvre mal tolérée.</p>"},{"i":"e5d1f593fbbc","n":166,"o":"166-11","u":"Prise en charge","t":"Connaître le traitement symptomatique","q":"Dans quel cas une antibiothérapie est-elle justifiée chez un patient atteint de grippe et quel est l'antibiotique recommandé ?","a":"<p>Une antibiothérapie est justifiée <strong>uniquement en cas de pneumonie bactérienne post-grippale</strong>. L'antibiotique recommandé est l'<strong>amoxicilline-acide clavulanique</strong>, pour une durée de <strong>7 jours</strong>.</p>"},{"i":"f8ffedc9acc1","n":166,"o":"166-11","u":"Prise en charge","t":"Connaître le traitement symptomatique","q":"Quels médicaments sont à proscrire dans le cadre du traitement symptomatique de la grippe ?","a":"<ul><li>Les <strong>Anti-Inflammatoires Non Stéroïdiens</strong> (AINS)</li><li>L'<strong>aspirine</strong></li><li>Les <strong>corticoïdes</strong></li><li>Les <strong>antitussifs</strong></li><li>Les <strong>fluidifiants bronchiques</strong></li></ul>"},{"i":"1e67c0675980","n":166,"o":"166-13","u":"Suivi et/ou pronostic","t":"Connaître les mesures de prévention de la transmission","q":"Quelles sont les mesures de prévention de la transmission de la grippe pour un patient ambulatoire ?","a":"<p>Pour un patient ambulatoire atteint de grippe, les mesures de prévention de la transmission incluent :</p><ul><li>Le <strong>repos à domicile</strong> et un <strong>arrêt de travail</strong> pour éviter la transmission.</li><li>Des <strong>mesures d'hygiène</strong> :<ul><li>Couvrir la bouche et le nez lors de la toux et des éternuements.</li><li>Utiliser des <strong>mouchoirs à usage unique</strong>, jetés dans une poubelle fermée.</li><li>Un <strong>lavage fréquent des mains</strong>.</li></ul></li></ul>"},{"i":"ebf19bd10558","n":166,"o":"166-13","u":"Suivi et/ou pronostic","t":"Connaître les mesures de prévention de la transmission","q":"Quelles sont les mesures de prévention de la transmission de la grippe pour un patient hospitalisé ?","a":"<p>Pour un patient hospitalisé atteint de grippe, les mesures de prévention de la transmission incluent :</p><ul><li>Des <strong>précautions complémentaires de type gouttelettes</strong>.</li><li>Une <strong>chambre individuelle</strong> avec la <strong>porte fermée</strong>.</li><li>Des <strong>mesures d'hygiène</strong> strictes.</li></ul>"},{"i":"fc73aaa08076","n":166,"o":"166-13","u":"Suivi et/ou pronostic","t":"Connaître les mesures de prévention de la transmission","q":"Quand et comment est envisagée une prophylaxie post-exposition à la grippe ?","a":"<p>Une prophylaxie post-exposition à la grippe est envisagée dans <strong>certaines situations</strong>, notamment lors de <strong>cas groupés dans un établissement hébergeant des personnes âgées</strong>. Elle consiste en l'administration d'<strong>Oseltamivir per os</strong> pendant <strong>10 jours</strong>.</p>"},{"i":"0e9a8c3ef6c9","n":166,"o":"166-14","u":"Suivi et/ou pronostic","t":"Connaître les indications du vaccin anti-grippal","q":"Quelles sont les contre-indications absolues à la vaccination grippale ?","a":"<p>La principale contre-indication à la vaccination grippale est l'<strong>allergie à l'ovalbumine</strong> (protéine de l'œuf).</p>"},{"i":"1ebb4a6cd2fb","n":166,"o":"166-14","u":"Suivi et/ou pronostic","t":"Connaître les indications du vaccin anti-grippal","q":"Pourquoi la vaccination grippale est-elle recommandée chez la femme enceinte ?","a":"<p>La vaccination grippale chez la femme enceinte protège la mère et confère un <strong>bénéfice indirect</strong> au nouveau-né et au nourrisson par le passage d'<strong>anticorps anti-grippaux maternels</strong>, ces derniers n'étant pas vaccinables avant l'âge de <strong>6 mois</strong>.</p>"},{"i":"2f29a31b873c","n":166,"o":"166-14","u":"Suivi et/ou pronostic","t":"Connaître les indications du vaccin anti-grippal","q":"Quelles sont les indications de la vaccination grippale chez les adultes sans comorbidités ?","a":"<ul><li><strong>Adultes de plus de 65 ans</strong>.</li><li>Les <strong>femmes enceintes</strong>, quel que soit le trimestre de la grossesse (recommandation particulière).</li><li>Les <strong>personnes obèses avec un IMC supérieur à 40</strong> (recommandation particulière).</li></ul>"},{"i":"4df26f60b811","n":166,"o":"166-14","u":"Suivi et/ou pronostic","t":"Connaître les indications du vaccin anti-grippal","q":"Quels sont les professionnels pour lesquels la vaccination grippale est recommandée ?","a":"<ul><li>Les <strong>professionnels de santé</strong> ou en contact avec des sujets à risque.</li><li>Le personnel naviguant.</li><li>Les guides touristiques.</li><li>Le personnel exposé aux <strong>virus porcins et aviaires</strong>.</li></ul>"},{"i":"defd93494960","n":166,"o":"166-14","u":"Suivi et/ou pronostic","t":"Connaître les indications du vaccin anti-grippal","q":"Quelle est la composition générale et le mode d'administration du vaccin contre la grippe en France ?","a":"<p>Le vaccin contre la grippe est un <strong>vaccin viral inactivé</strong>, <strong>quadrivalent</strong> (2 souches A + 2 souches B), administré par <strong>1 injection intramusculaire</strong>. Sa composition est <strong>réactualisée chaque année</strong>, nécessitant une vaccination annuelle à l'automne.</p>"},{"i":"ed7c35be7e7b","n":166,"o":"166-14","u":"Suivi et/ou pronostic","t":"Connaître les indications du vaccin anti-grippal","q":"Quelles sont les principales comorbidités qui justifient une indication à la vaccination grippale chez un patient âgé de 6 mois ou plus ?","a":"<ul><li>Affections <strong>bronchopulmonaires chroniques</strong> (asthme, BPCO).</li><li><strong>Cardiopathies</strong> graves (insuffisance cardiaque, troubles du rythme, coronaropathie).</li><li>Antécédents d'<strong>AVC</strong>.</li><li>Affections <strong>neuro-musculaires graves</strong> (paraplégie/tétraplégie avec atteinte diaphragmatique).</li><li><strong>Néphropathies chroniques graves</strong> / Syndrome néphrotique.</li><li><strong>Diabète</strong> (type 1 et 2).</li><li><strong>Déficits immunitaires</strong> (VIH, drépanocytose).</li><li>Maladie <strong>hépatique chronique</strong>.</li><li>Les patients <strong>séjournant en SSR</strong> / établissement médico-social.</li></ul>"},{"i":"65d03ca09708","n":166,"o":"166-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une grippe","q":"Dans quel contexte doit-on évoquer une grippe face à une toux fébrile ?","a":"<p>On doit évoquer une grippe face à une toux fébrile si elle survient :</p><ul><li>Lors d'une <strong>épidémie</strong> (généralement de <strong>novembre à mars en Europe</strong>).</li><li>Après un <strong>contact</strong> avec une personne atteinte.</li></ul>"},{"i":"86bb32a2bb25","n":166,"o":"166-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une grippe","q":"Quelles sont les caractéristiques de la phase d'invasion de la grippe ?","a":"<p>La phase d'invasion de la grippe se caractérise par :</p><ul><li>Un <strong>début brutal</strong>.</li><li>Un <strong>malaise général fébrile</strong> avec :</li><ul><li><strong>Frissons</strong>.</li><li><strong>Fièvre élevée</strong>.</li><li><strong>Myalgies</strong>.</li><li><strong>Céphalées</strong>.</li></ul></ul>"},{"i":"e7428917c26d","n":166,"o":"166-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une grippe","q":"Quels sont les signes cliniques de la phase d'état de la grippe ?","a":"<p>La phase d'état de la grippe présente :</p><ul><li>Des <strong>signes généraux intenses</strong> :</li><ul><li><strong>Fièvre à 39-40 °C</strong>, frissons.</li><li>Asthénie, anorexie, abattement (avec une <strong>courbe de fièvre en V grippal</strong>).</li></ul><li>Un <strong>syndrome algique diffus</strong> : céphalées frontales et rétro-orbitaires, arthromyalgies, lombalgies, courbatures.</li><li>Des <strong>signes ORL</strong> : congestion nasale, rhinorrhée.</li><li>Une <strong>pharyngo-laryngite</strong> : douleurs pharyngo-laryngées, dysphagie, dysphonie.</li><li>Des <strong>signes trachéo-bronchiques</strong> : <strong>toux sèche et douloureuse</strong> (brûlures rétrosternales).</li><li>Des <strong>signes physiques pauvres</strong> : énanthème pharyngé, râles sous-crépitants.</li></ul>"},{"i":"5d19ca778902","n":166,"o":"166-5","u":"Suivi et/ou pronostic","t":"Connaître les complications de la grippe","q":"Quelles sont les surinfections bactériennes possibles après une grippe ?","a":"<p>Les surinfections bactériennes des voies aériennes sont fréquentes et peuvent se traduire par :</p><ul><li>Une <strong>pneumonie bactérienne</strong></li><li>Une <strong>otite moyenne aiguë</strong> (OMA)</li><li>Une <strong>sinusite aiguë</strong></li></ul>"},{"i":"63628e1be6b7","n":166,"o":"166-5","u":"Suivi et/ou pronostic","t":"Connaître les complications de la grippe","q":"Quelles sont les complications de la grippe chez la femme enceinte ?","a":"<p>Chez la femme enceinte, la grippe peut entraîner une <strong>surmortalité maternelle</strong>, principalement par complications cardio-respiratoires. Les risques fœtaux comprennent l'<strong>avortement</strong> et la <strong>prématurité</strong>. Il est important de noter que le virus de la grippe n'est <strong>pas tératogène</strong>.</p>"},{"i":"841a88095d8a","n":166,"o":"166-5","u":"Suivi et/ou pronostic","t":"Connaître les complications de la grippe","q":"Qu'est-ce qu'une grippe maligne primaire et quelles sont ses caractéristiques ?","a":"<p>La grippe maligne primaire est une complication rare et grave, caractérisée par une <strong>pneumopathie alvéolo-interstitielle hypoxémiante</strong> rapidement évolutive vers un <strong>SDRA</strong> (Syndrome de Détresse Respiratoire Aiguë) sans interrègne après la déclaration des symptômes grippaux. Elle nécessite une <strong>hospitalisation en réanimation</strong>.</p>"},{"i":"88453f7e1c18","n":166,"o":"166-5","u":"Suivi et/ou pronostic","t":"Connaître les complications de la grippe","q":"Quelles sont les complications extra-respiratoires possibles de la grippe ?","a":"<ul><li><strong>Myocardite</strong> ou <strong>péricardite</strong></li><li><strong>Encéphalite</strong></li><li><strong>Rhabdomyolyse</strong></li><li>Troubles digestifs (notamment la <strong>diarrhée</strong>)</li></ul>"},{"i":"dcba4f33a20f","n":166,"o":"166-5","u":"Suivi et/ou pronostic","t":"Connaître les complications de la grippe","q":"Quel est le risque lié à la prise d'aspirine chez l'enfant atteint de grippe ?","a":"<p>La prise d'aspirine chez l'enfant atteint de grippe (surtout de type B) expose à un risque de <strong>Syndrome de Reye</strong>, caractérisé par une association clinique d'<strong>encéphalite aiguë</strong> et d'<strong>hépatite fulminante</strong>. L'aspirine est donc contre-indiquée chez l'enfant grippé.</p>"},{"i":"32d436b64c85","n":166,"o":"166-6","u":"Identifier une urgence","t":"Connaître les terrains à risque de complications","q":"Quelles sont les insuffisances d'organes spécifiques qui exposent à un risque accru de décompensation et de complications graves en cas de grippe ?","a":"Les insuffisances d'organes spécifiques qui exposent un risque accru de décompensation et de complications graves en cas de grippe sont :<ul><li>L'<strong>insuffisance rénale</strong>.</li><li>L'<strong>insuffisance respiratoire</strong>.</li><li>L'<strong>insuffisance cardiaque</strong>.</li></ul>"},{"i":"9dabfd5376f6","n":166,"o":"166-6","u":"Identifier une urgence","t":"Connaître les terrains à risque de complications","q":"Quels sont les terrains physiologiques à risque de complications graves de la grippe, justifiant une vigilance particulière ?","a":"Les terrains physiologiques à risque de complications graves de la grippe sont :<ul><li>Le <strong>sujet âgé</strong>.</li><li>Le <strong>nourrisson de moins de 6 mois</strong>.</li><li>La <strong>femme enceinte</strong>.</li></ul>"},{"i":"faf9274e40b3","n":166,"o":"166-6","u":"Identifier une urgence","t":"Connaître les terrains à risque de complications","q":"Quelles sont les maladies chroniques identifiées comme terrains à risque de complications graves de la grippe ?","a":"Les maladies chroniques qui augmentent le risque de complications graves de la grippe sont :<ul><li>L'<strong>immunodépression</strong>.</li><li>La <strong>drépanocytose</strong>.</li><li>Le <strong>diabète</strong>.</li><li>L'<strong>obésité</strong>.</li></ul>"},{"i":"756147593539","n":166,"o":"166-9","u":"Examens complémentaires","t":"Connaître les indications et non indication des examens paracliniques","q":"Dans quel cas, lors d'une grippe saisonnière non compliquée, doit-on réaliser un examen microbiologique ?","a":"<p>En cas de grippe saisonnière non compliquée, il n'y a <strong>aucune indication</strong> à réaliser un examen microbiologique. Le diagnostic est <strong>clinique</strong>.</p>"},{"i":"e46ecc8aa96b","n":166,"o":"166-9","u":"Examens complémentaires","t":"Connaître les indications et non indication des examens paracliniques","q":"Quels sont les résultats possibles d'une radiographie thoracique réalisée dans le cadre d'une grippe ?","a":"<ul><li>Une radiographie <strong>normale</strong>.</li><li>Un <strong>syndrome alvéolo-interstitiel bilatéral</strong> (suggérant une pneumonie grippale primaire).</li><li>Une <strong>condensation parenchymateuse</strong> (suggérant une pneumonie bactérienne secondaire).</li></ul>"},{"i":"f2585721c29e","n":166,"o":"166-9","u":"Examens complémentaires","t":"Connaître les indications et non indication des examens paracliniques","q":"Quelles sont les indications de réalisation d'un examen microbiologique dans le cadre de la grippe ?","a":"<ul><li>Une visée <strong>épidémiologique</strong> (par exemple, pour les médecins du réseau Sentinelles).</li><li>Une visée <strong>étiologique</strong> chez un patient hospitalisé présentant des complications respiratoires ou extra-respiratoires (afin de guider les précautions d'hygiène et le traitement).</li></ul>"}]};